USE ai_interviewer;

-- HTML 200 MCQs
-- Source: Pasted text.txt
-- Difficulty mapping (source did not specify difficulty): Q1-50 = Easy, Q51-150 = Medium, Q151-200 = Hard.
-- Existing 60 HTML questions were deleted before this insert.


-- Verification
SELECT COUNT(*) AS html_questions
FROM questions
WHERE skill = 'HTML';

SELECT COUNT(DISTINCT question) AS unique_html_questions
FROM questions
WHERE skill = 'HTML';

SELECT skill, COUNT(*) AS question_count
FROM questions
GROUP BY skill
ORDER BY skill;

DELETE FROM questions
WHERE id IN (
    SELECT id
    FROM (
        SELECT id
        FROM questions
        WHERE skill = 'JavaScript'
    ) AS temp
);

